package com.mtaimproved;

/**
 * A line of the alchemist's cupboard table: what the item is called, what alchemising it pays, and
 * whether it is the one the game is pointing its arrow at, which costs no runes to cast on.
 */
class AlchemyItem
{
	private final String name;
	private final int item;
	private final int coins;
	private final boolean free;

	AlchemyItem(String name, int item, int coins, boolean free)
	{
		this.name = name;
		this.item = item;
		this.coins = coins;
		this.free = free;
	}

	String name()
	{
		return name;
	}

	/** The arena's own copy of the item, which is what the cupboard hands out. */
	int item()
	{
		return item;
	}

	int coins()
	{
		return coins;
	}

	boolean free()
	{
		return free;
	}
}

package com.mtaimproved;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * A row of the panel whose left or right half is an item's icon instead of its name, laid out the
 * way {@code LineComponent} lays its two halves out so a box of icons lines up with a box of text.
 * The icon sits where the words it stands in for would have been.
 */
class IconLine implements LayoutableRenderableEntity
{
	private BufferedImage leftImage;
	private BufferedImage rightImage;
	private String leftText = "";
	private String rightText = "";
	private Color leftColour = Color.WHITE;
	private Color rightColour = Color.WHITE;

	/** Whether a row keeps the arrow's place free at its right end, and whether it draws one there. */
	private boolean gutter;
	private boolean arrow;
	private Color arrowColour = Color.WHITE;

	/** Between the arrow and the number it points at. */
	private static final int ARROW_GAP = 3;

	/** The least space left between the two halves of a row, so they never read as one. */
	private static final int GAP = 16;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);
	private final Rectangle bounds = new Rectangle();

	IconLine left(BufferedImage image)
	{
		leftImage = image;
		return this;
	}

	IconLine left(String text)
	{
		leftText = text;
		return this;
	}

	IconLine right(BufferedImage image)
	{
		rightImage = image;
		return this;
	}

	IconLine right(String text)
	{
		rightText = text;
		return this;
	}

	IconLine colour(Color colour)
	{
		leftColour = colour;
		rightColour = colour;
		return this;
	}

	IconLine rightColour(Color colour)
	{
		rightColour = colour;
		return this;
	}

	/**
	 * Keeps room at the right end of the row for an arrow pointing back at it, and draws one there
	 * when this is the row being pointed at. The room is kept either way, so a column of numbers
	 * lines up whether its row is the one with the arrow or not.
	 */
	IconLine arrow(boolean point, Color colour)
	{
		gutter = true;
		arrow = point;
		arrowColour = colour;
		return this;
	}

	/**
	 * How wide this row wants the box to be: both halves, the space between them, and the arrow's
	 * place at the end where one is kept. A box narrower than this is a box whose two halves run into
	 * each other.
	 */
	int width(FontMetrics metrics)
	{
		int height = metrics.getHeight();
		int left = leftImage != null ? width(leftImage, height) : metrics.stringWidth(leftText);
		int right = rightImage != null ? width(rightImage, height) : metrics.stringWidth(rightText);
		return left + GAP + right + (gutter ? height / 2 + ARROW_GAP : 0);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int height = metrics.getHeight();
		int x = preferredLocation.x;
		int top = preferredLocation.y;
		int baseline = top + metrics.getAscent();

		if (leftImage != null)
		{
			draw(graphics, leftImage, x, top, height);
		}
		else if (!leftText.isEmpty())
		{
			write(graphics, leftText, x, baseline, leftColour);
		}

		int right = x + preferredSize.width;
		if (gutter)
		{
			int size = height / 2;
			if (arrow)
			{
				point(graphics, right - size, top + height / 2, size);
			}

			right -= size + ARROW_GAP;
		}

		if (rightImage != null)
		{
			draw(graphics, rightImage, right - width(rightImage, height), top, height);
		}
		else if (!rightText.isEmpty())
		{
			write(graphics, rightText, right - metrics.stringWidth(rightText), baseline, rightColour);
		}

		Dimension dimension = new Dimension(preferredSize.width, height);
		bounds.setLocation(preferredLocation);
		bounds.setSize(dimension);
		return dimension;
	}

	/** An arrow pointing left, back along its own row at what the row is about. */
	private void point(Graphics2D graphics, int x, int middle, int size)
	{
		int half = Math.max(1, size / 2);
		Polygon triangle = new Polygon(
			new int[]{x, x + size, x + size},
			new int[]{middle, middle - half, middle + half},
			3);

		graphics.setColor(arrowColour);
		graphics.fill(triangle);
	}

	/**
	 * An item's icon comes at the size the game draws it in an inventory, which is taller than a line
	 * of text and would leave the box full of gaps, so it is drawn down to the height of the words it
	 * stands in for.
	 */
	private static void draw(Graphics2D graphics, BufferedImage image, int x, int y, int height)
	{
		Object was = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.drawImage(image, x, y, width(image, height), height, null);

		if (was != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, was);
		}
	}

	private static int width(BufferedImage image, int height)
	{
		return Math.max(1, image.getWidth() * height / image.getHeight());
	}

	private static void write(Graphics2D graphics, String text, int x, int y, Color colour)
	{
		TextComponent component = new TextComponent();
		component.setText(text);
		component.setColor(colour);
		component.setPosition(new Point(x, y));
		component.render(graphics);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point location)
	{
		preferredLocation = location;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		preferredSize = dimension;
	}
}

