package com.mtaimproved;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

class MtaImprovedOverlay extends OverlayPanel
{
	/** The item that casts for free, and the arrow pointing at it. */
	private static final Color GOOD = new Color(0, 200, 83);

	/** An item worth less than the best one on the table. */
	private static final Color LESSER = new Color(170, 170, 170);

	/** Narrower than this and the box is a sliver, however little it has to say. */
	private static final int LEAST_WIDTH = 70;

	private final MtaImprovedPlugin plugin;
	private final MtaImprovedConfig config;
	private final ItemManager itemManager;

	/** The rows of the box, kept while they are measured and given to the panel once it is sized. */
	private final List<IconLine> rows = new ArrayList<>();

	@Inject
	MtaImprovedOverlay(MtaImprovedPlugin plugin, MtaImprovedConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, "MTA Improved overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Room[] rooms = plugin.shown();
		List<AlchemyItem> items = config.alchemyItems() ? plugin.alchemy() : Collections.emptyList();
		if (rooms.length == 0 && items.isEmpty())
		{
			return null;
		}

		boolean icons = config.shortLabels();

		// The cupboard table's arrow stands to the right of its numbers, so every row in the box keeps
		// that same space free while the table is up. Without it the table's numbers would sit a few
		// pixels in from the points above them, which reads as a column that has slipped
		boolean gutter = !items.isEmpty();

		rows.clear();
		for (Room room : rooms)
		{
			points(room, icons, gutter);
		}

		maze(gutter);
		shape(icons, gutter);
		alchemy(items, icons);

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("MTA")
			.color(Color.WHITE)
			.build());

		// The box is as wide as the widest row wants it rather than a width picked in advance, so
		// counting points towards a reward, which writes a number several times longer than a plain
		// total, widens the box instead of writing over the name beside it
		FontMetrics metrics = graphics.getFontMetrics();
		int width = LEAST_WIDTH;
		for (IconLine row : rows)
		{
			width = Math.max(width, row.width(metrics));
			panelComponent.getChildren().add(row);
		}

		rows.clear();
		panelComponent.setPreferredSize(new Dimension(width, 0));
		return super.render(graphics);
	}

	/** A room's row: what you have, how many are still to go, or the one out of the other. */
	private void points(Room room, boolean icons, boolean gutter)
	{
		int points = plugin.points(room);
		int target = plugin.target(room);
		int needed = plugin.needed(room);

		boolean counting = target > 0 && config.display() != MtaImprovedConfig.Display.POINTS;
		String right;
		if (!counting)
		{
			right = format(points);
		}
		else if (config.display() == MtaImprovedConfig.Display.NEEDED)
		{
			right = format(needed);
		}
		else
		{
			right = format(points) + " / " + format(target);
		}

		add(new IconLine()
			.left(icons ? room.shortLabel() : room.label())
			.right(right)
			.rightColour(target > 0 ? progress(points, target) : Color.WHITE), gutter);
	}

	/**
	 * Red at none of the way there, through to green at all of it, so a glance at the number says how
	 * far off the rewards being saved for are. Only the number is coloured; the room keeps its own
	 * name white, so the box still reads as a list of rooms.
	 */
	private static Color progress(int points, int target)
	{
		float part = Math.min(1f, (float) points / target);

		// A third of the way round the colour wheel is red to green, by way of orange and yellow
		return Color.getHSBColor(part / 3f, 1f, 0.95f);
	}

	/**
	 * How far along the run of mazes the theatre pays the bonus for the player is, green on the maze
	 * that pays it.
	 */
	private void maze(boolean gutter)
	{
		int done = plugin.bonus();
		if (done < 0)
		{
			return;
		}

		int run = MtaImprovedPlugin.BONUS_MAZES;
		add(new IconLine()
			.left("Bonus")
			.right(done + " / " + run)
			.rightColour(done == run - 1 ? GOOD : Color.WHITE), gutter);
	}

	/**
	 * The shape the enchantment chamber pays the bonus for. Named while the box is writing words, and
	 * in short mode the shape's own icon in place of the name, which says what to look for on the
	 * table without reading anything.
	 */
	private void shape(boolean icons, boolean gutter)
	{
		Shape shape = plugin.shape();
		if (shape == null)
		{
			return;
		}

		IconLine line = new IconLine().left("Bonus");
		add(icons ? line.right(itemManager.getImage(shape.item())) : line.right(shape.label()), gutter);
	}

	/**
	 * The cupboard table, which the game keeps in the same box as the alchemist's points and so goes
	 * with them. Best paying item at the top, and the one the game is pointing its arrow at, which
	 * casts without runes, in green with an arrow of its own pointing at it.
	 */
	private void alchemy(List<AlchemyItem> items, boolean icons)
	{
		if (items.isEmpty())
		{
			return;
		}

		int best = items.get(0).coins();
		for (AlchemyItem item : items)
		{
			Color colour = item.free() ? GOOD : item.coins() == best ? Color.WHITE : LESSER;
			IconLine line = new IconLine()
				.right(Integer.toString(item.coins()))
				.colour(colour)
				.arrow(item.free(), GOOD);

			rows.add(icons ? line.left(itemManager.getImage(item.item())) : line.left(item.name()));
		}
	}

	/** Every row keeps the arrow's space free while the cupboard table is up, so the numbers line up. */
	private void add(IconLine line, boolean gutter)
	{
		rows.add(gutter ? line.arrow(false, GOOD) : line);
	}

	private static String format(int points)
	{
		return String.format("%,d", points);
	}
}

package com.mtaimproved;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Arrays;
