@Slf4j
@PluginDescriptor(
	name = "MTA Improved",
	description = "Puts your Mage Training Arena points in an overlay instead of the game's own box",
	tags = {"mage", "training", "arena", "mta", "pizazz", "pizzaz", "points", "magic", "infinity"}
)
public class MtaImprovedPlugin extends Plugin
{
	static final Room[] ROOMS = Room.values();

	/** The box in the entrance hall, which lists all four rooms at once. */
	private static final int HALL_BOX = InterfaceID.MagictrainingMain.CONTENTS;

	/** The five cupboard items, their coin values and the arrow marking the one that casts free. */
	private static final int[] ITEMS = {
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM1,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM2,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM3,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM4,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM5
	};

	/**
	 * The cupboard's five items, in the order its table lists them. The names are written into the
	 * interface rather than sent, so a slot is always the same item and only its price moves.
	 */
	private static final int[] ITEM_IDS = {
		ItemID.MAGICTRAINING_LEATHER_BOOTS,
		ItemID.MAGICTRAINING_ADAMANT_KITESHIELD,
		ItemID.MAGICTRAINING_ADAMANT_MED_HELM,
		ItemID.MAGICTRAINING_EMERALD,
		ItemID.MAGICTRAINING_RUNE_LONGSWORD
	};

	private static final int[] COSTS = {
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_COST1,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_COST2,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_COST3,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_COST4,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_COST5
	};

	private static final int[] ARROWS = {
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_LAY1,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_LAY2,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_LAY3,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_LAY4,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_LAY5
	};

	/**
	 * The arena's ground floor, where the four doors and the reward shop are, along with the ground
	 * outside it. The box listing all four rooms belongs here.
	 */
	private static final int HALL_REGION = 13363;

	private static final Room[] NOTHING = new Room[0];

	/** No points known for a room, because nothing on screen has said what they are. */
	private static final int UNKNOWN = -1;

	/** Mazes to a run in the theatre: the fifth one solved is the one that pays the bonus. */
	static final int BONUS_MAZES = 5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MtaImprovedConfig config;

	@Inject
	private MtaImprovedOverlay overlay;

	/**
	 * The points last seen for each room. Only the game's own boxes know them, so a room's figure
	 * stands until something on screen says otherwise.
	 */
	private final int[] points = new int[ROOMS.length];

	/** Everything hidden to take the game's points off the screen, so only that is handed back. */
	private final Set<Integer> hidden = new HashSet<>();

	/** The cupboard table as it stands, best paying item first. Empty outside the alchemist's room. */
	private List<AlchemyItem> alchemy = Collections.emptyList();

	/** The shape the enchantment chamber is asking for, or null outside that room. */
	private Shape shape;

	/**
	 * Mazes solved in the theatre, as its own box counts them, or UNKNOWN away from the theatre.
	 */
	private int solved = UNKNOWN;

	/** The room being played, which is the room the player is standing in. */
	private Room room;

	/** Whether any of the arena's boxes are loaded, which is the arena and nowhere else. */
	private boolean inArena;

	@Provides
	MtaImprovedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MtaImprovedConfig.class);
	}

	@Override
	protected void startUp()
	{
		reset();
		overlayManager.add(overlay);
		clientThread.invoke(this::update);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientThread.invoke(this::restoreBoxes);
		reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		// The points belong to whoever is logged in, and the interfaces are gone either way
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MtaImprovedConfig.GROUP.equals(event.getGroup()) && !config.hideGameBox())
		{
			clientThread.invoke(this::restoreBoxes);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		update();
	}

	private void update()
	{
		Room was = room;
		boolean wasInArena = inArena;

		room = currentRoom();
		inArena = inArena();
		readPoints();
		readAlchemy();
		shape = room == Room.ENCHANTMENT ? bonusShape() : null;
		solved = room == Room.TELEKINETIC ? number(InterfaceID.MagictrainingTele.MAGICTRAIN_MAZE_NUMBER) : UNKNOWN;

		if (room != was || inArena != wasInArena)
		{
			log.debug("room {} arena {} at {} points {} alchemy {} shape {}", room, inArena, where(),
				Arrays.toString(points), alchemy.size(), shape);
		}
	}

	/**
	 * Takes the game's boxes off the screen every frame rather than every tick. The arena puts a box
	 * up part way through a tick, and a tick is several frames, so hiding it on the tick leaves it on
	 * screen for the few frames in between, which is the flash of the game's own box.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (config.hideGameBox())
		{
			hideBoxes();
		}
	}

	/** The same, the moment a box is built, so it is hidden before it is ever drawn. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (config.hideGameBox())
		{
			hideBoxes();
		}
	}

	/**
	 * The room the player is standing in. Three of them are floors of the arena, so where the player
	 * is says which one; the telekinetic theatre is put together away from the building, so its box
	 * being loaded is what says they are in it.
	 * <p>
	 * Which boxes are loaded cannot answer this on its own. The arena keeps more than one of them
	 * loaded at a time, so going by that reads as being in two rooms at once.
	 */
	private Room currentRoom()
	{
		WorldPoint location = location();
		if (location == null)
		{
			return null;
		}

		for (Room candidate : ROOMS)
		{
			if (candidate.isOn(location.getRegionID(), location.getPlane()))
			{
				return candidate;
			}
		}

		return client.getWidget(InterfaceID.MagictrainingTele.UNIVERSE) != null ? Room.TELEKINETIC : null;
	}

	/** Whether the player is in the arena at all, which is the four rooms and the hall they open off. */
	private boolean inArena()
	{
		if (room != null)
		{
			return true;
		}

		WorldPoint location = location();
		if (location == null)
		{
			return false;
		}

		int region = location.getRegionID();
		if (region == Room.REGION)
		{
			return true;
		}

		// The ground outside the arena shares a region with its hall, so the box listing all four
		// rooms being loaded is what tells the two apart
		return region == HALL_REGION && client.getWidget(HALL_BOX) != null;
	}

	private WorldPoint location()
	{
		Player player = client.getLocalPlayer();
		return player == null ? null : player.getWorldLocation();
	}

	/** Only ever read for the log. */
	private String where()
	{
		WorldPoint location = location();
		return location == null ? "nowhere" : location.getRegionID() + "/" + location.getPlane();
	}

	/**
	 * Whether the game has a component on screen. A component hidden here counts as on screen, so
	 * the arrow marking the free item can still be read inside a box this has taken away.
	 */
	private boolean drawn(int component)
	{
		Widget widget = client.getWidget(component);
		if (widget == null)
		{
			return false;
		}

		for (Widget part = widget; part != null; part = part.getParent())
		{
			if (part.isSelfHidden() && !hidden.contains(part.getId()))
			{
				return false;
			}
		}

		return true;
	}

	/**
	 * Takes each room's points off whichever of the game's boxes is showing them. A room left unsaid
	 * keeps the figure it had, which is what lets the entrance hall still read right while the box
	 * listing all four is between being loaded and not.
	 */
	private void readPoints()
	{
		for (Room candidate : ROOMS)
		{
			int shown = number(candidate.points());
			if (shown < 0)
			{
				shown = number(candidate.hallPoints());
			}

			if (shown >= 0)
			{
				points[candidate.ordinal()] = shown;
			}
		}
	}

	/**
	 * The cupboard table, read off the game's own box so it is right through every rotation. Best
	 * paying item first, since that is the one worth going looking for.
	 */
	private void readAlchemy()
	{
		if (room != Room.ALCHEMIST)
		{
			alchemy = Collections.emptyList();
			return;
		}

		List<AlchemyItem> items = new ArrayList<>(ITEMS.length);
		for (int i = 0; i < ITEMS.length; i++)
		{
			String name = text(ITEMS[i]);
			int coins = number(COSTS[i]);
			if (name.isEmpty() || coins < 0)
			{
				continue;
			}

			// The game writes the name with a colon after it, which a column of its own does not need
			if (name.endsWith(":"))
			{
				name = name.substring(0, name.length() - 1);
			}

			items.add(new AlchemyItem(name, ITEM_IDS[i], coins, drawn(ARROWS[i])));
		}

		items.sort((one, other) -> Integer.compare(other.coins(), one.coins()));
		alchemy = items;
	}

	/**
	 * The shape the chamber is asking for, which is the one it has put on the right of the screen.
	 */
	private Shape bonusShape()
	{
		for (Shape candidate : Shape.values())
		{
			if (drawn(candidate.layer()))
			{
				return candidate;
			}
		}

		return null;
	}

	/**
	 * The number a box is showing, or -1 if it is not on screen or is not a number. Hiding a box
	 * leaves its text alone, so this reads the same whether the game's points are on screen or not.
	 */
	private int number(int component)
	{
		String text = text(component).replace(",", "");
		if (text.isEmpty() || text.length() > 9)
		{
			return UNKNOWN;
		}

		for (int i = 0; i < text.length(); i++)
		{
			if (!Character.isDigit(text.charAt(i)))
			{
				return UNKNOWN;
			}
		}

		return Integer.parseInt(text);
	}

	private String text(int component)
	{
		Widget widget = client.getWidget(component);
		return widget == null ? "" : Text.removeTags(widget.getText()).trim();
	}

	/**
	 * Hides every one of the arena's points boxes that is loaded, rather than only the room being
	 * played. The arena holds more than one of them loaded at a time, and a box for a room the player
	 * is not in is no more wanted on screen than the one for the room they are.
	 */
	private void hideBoxes()
	{
		for (Room candidate : ROOMS)
		{
			hide(candidate.box());
			if (candidate.bonusBox() >= 0)
			{
				hide(candidate.bonusBox());
			}
		}

		hide(HALL_BOX);
	}

	private void hide(int component)
	{
		Widget widget = client.getWidget(component);
		if (widget == null || widget.isSelfHidden())
		{
			return;
		}

		widget.setHidden(true);
		hidden.add(component);
	}

	/**
	 * Hands back only what was hidden here, so a box the game has its own reasons to hide stays that
	 * way.
	 */
	private void restoreBoxes()
	{
		for (int component : hidden)
		{
			Widget widget = client.getWidget(component);
			if (widget != null)
			{
				widget.setHidden(false);
			}
		}

		hidden.clear();
	}

	/**
	 * The rooms the overlay lists: the room being played, all four, or none of them, whichever the
	 * player asked for, and always all four in the hall, the same as the box this stands in for.
	 * Empty outside the arena, so the overlay is only up in it.
	 */
	Room[] shown()
	{
		if (!inArena)
		{
			return NOTHING;
		}

		// The hall is where the game lists all four, so that is what stands in for it
		if (room == null)
		{
			return ROOMS;
		}

		switch (config.rooms())
		{
			case ALL:
				return ROOMS;
			case NONE:
				return NOTHING;
			default:
				return new Room[]{room};
		}
	}

	/** The shape to enchant, or null when the player is not in the enchantment chamber. */
	Shape shape()
	{
		return shape;
	}

	/**
	 * How far along the run of mazes the theatre pays extra for the player is, or -1 away from the
	 * theatre. Every fifth maze solved is the one worth the bonus, and the theatre's own box counts
	 * the mazes rather than the run, so the run is what is left over when the fives are taken out.
	 */
	int bonus()
	{
		return solved < 0 ? -1 : solved % BONUS_MAZES;
	}

	/** The cupboard table, or empty when the player is not in the alchemist's room. */
	List<AlchemyItem> alchemy()
	{
		return alchemy;
	}

	int points(Room room)
	{
		return points[room.ordinal()];
	}

	/** What the rewards being saved for cost in a room, which is nothing if none are ticked. */
	int target(Room room)
	{
		int target = 0;
		for (Reward reward : Reward.values())
		{
			if (reward.chosen(config))
			{
				target += reward.cost(room);
			}
		}

		return target;
	}

	int needed(Room room)
	{
		return Math.max(0, target(room) - points(room));
	}

	private void reset()
	{
		Arrays.fill(points, 0);
		hidden.clear();
		alchemy = Collections.emptyList();
		shape = null;
		solved = UNKNOWN;
		room = null;
		inArena = false;
	}
}

package com.mtaimproved;

/**
 * What the arena sells, and what each of its rooms charges for it. The runes it also sells cost a
 * point or two and are bought with whatever is left over, so they are not worth saving towards and
 * are left out.
 * <p>
 * A wand past the first is handed the wand below it as well as the points, which costs no points of
 * its own, so working up through the tiers one at a time is a matter of ticking each of them.
 */
enum Reward
{
	BEGINNER_WAND("Beginner wand", 30, 30, 300, 30),
	APPRENTICE_WAND("Apprentice wand", 60, 60, 600, 60),
	TEACHER_WAND("Teacher wand", 150, 200, 1500, 150),
	MASTER_WAND("Master wand", 240, 240, 2400, 240),
	INFINITY_BOOTS("Infinity boots", 120, 120, 1200, 120),
	INFINITY_GLOVES("Infinity gloves", 175, 225, 1500, 175),
	INFINITY_HAT("Infinity hat", 350, 400, 3000, 350),
	INFINITY_TOP("Infinity top", 400, 450, 4000, 400),
	INFINITY_BOTTOMS("Infinity bottoms", 450, 500, 5000, 450),
	MAGES_BOOK("Mage's book", 500, 550, 6000, 500),
	RUNE_POUCH("Rune pouch", 150, 200, 1500, 150),
	BONES_TO_PEACHES("Bones to Peaches", 200, 300, 2000, 200);

	private final String label;

	/** What it costs in each room, in the order the rooms are listed. */
	private final int[] costs;

	Reward(String label, int telekinetic, int alchemist, int enchantment, int graveyard)
	{
		this.label = label;
		this.costs = new int[]{telekinetic, alchemist, enchantment, graveyard};
	}

	String label()
	{
		return label;
	}

	int cost(Room room)
	{
		return costs[room.ordinal()];
	}

	/**
	 * Whether this is one of the rewards being saved towards. Asked of each of them in turn rather
	 * than looked up, since what the settings hold is a tick box per reward.
	 */
	boolean chosen(MtaImprovedConfig config)
	{
		switch (this)
		{
			case BEGINNER_WAND:
				return config.beginnerWand();
			case APPRENTICE_WAND:
				return config.apprenticeWand();
			case TEACHER_WAND:
				return config.teacherWand();
			case MASTER_WAND:
				return config.masterWand();
			case INFINITY_BOOTS:
				return config.infinityBoots();
			case INFINITY_GLOVES:
				return config.infinityGloves();
			case INFINITY_HAT:
				return config.infinityHat();
			case INFINITY_TOP:
				return config.infinityTop();
			case INFINITY_BOTTOMS:
				return config.infinityBottoms();
			case MAGES_BOOK:
				return config.magesBook();
			case RUNE_POUCH:
				return config.runePouch();
			case BONES_TO_PEACHES:
				return config.bonesToPeaches();
			default:
				return false;
		}
	}
}

package com.mtaimproved;

import net.runelite.api.gameval.InterfaceID;

/**
 * The four rooms of the arena, each with its own points. Listed in the order the box in the entrance
 * hall lists them, so the overlay reads the same way round when it stands in for that one.
 */
enum Room
{
	TELEKINETIC("Telekinetic", "Tele", -1,
		InterfaceID.MagictrainingTele.MAGICTRAIN_TELE_PTS,
		InterfaceID.MagictrainingMain.MAGICTRAIN_TELE_POINTS,
		InterfaceID.MagictrainingTele.CONTENT_TOP,
		InterfaceID.MagictrainingTele.CONTENT_RIGHT),
	ALCHEMIST("Alchemist", "Alch", 2,
		InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_PTS,
		InterfaceID.MagictrainingMain.MAGICTRAIN_ALCH_POINTS,
		InterfaceID.MagictrainingAlchem.CONTENTS,
		-1),
	ENCHANTMENT("Enchantment", "Ench", 0,
		InterfaceID.MagictrainingEncha.MAGICTRAIN_ENCHA_PTS,
		InterfaceID.MagictrainingMain.MAGICTRAIN_ENCH_POINTS,
		InterfaceID.MagictrainingEncha.CONTENT_TOP,
		InterfaceID.MagictrainingEncha.CONTENT_RIGHT),
	GRAVEYARD("Graveyard", "Grave", 1,
		InterfaceID.MagictrainingGrave.MAGICTRAIN_GRAVE_PTS,
		InterfaceID.MagictrainingMain.MAGICTRAIN_GRAVE_POINTS,
		InterfaceID.MagictrainingGrave.CONTENT_TOP,
		-1);

	/**
	 * The three rooms built into the arena are floors of one region, one room to a floor. The
	 * telekinetic theatre is not one of them: its maze is put together away from the building, so it
	 * is known by its box being loaded instead.
	 */
	static final int REGION = 13462;

	private final String label;

	/** The room's name cut down to the few letters that still say which room it is. */
	private final String shortLabel;

	/** The floor of the arena this room is, or -1 for the theatre, which is not one of them. */
	private final int plane;

	/**
	 * The number in the room's own box. The game only draws that box in the room it belongs to, so
	 * whether it is on screen is also what says which room the player is in.
	 */
	private final int points;

	/** The number for this room in the box in the entrance hall, which lists all four at once. */
	private final int hallPoints;

	/**
	 * The layer holding the room's points, hidden to take them off the screen. In three of the rooms
	 * this layer holds nothing else; the alchemist's also holds the cupboard table, which the overlay
	 * takes over rather than leaving half a box behind.
	 */
	private final int box;

	/**
	 * The room's side box, where it keeps the bonus the overlay now says: the theatre's count of
	 * mazes solved and the chamber's shape worth extra. -1 where a room's side box holds something
	 * else, the graveyard's bones to hand, which is left to the game.
	 */
	private final int bonusBox;

	Room(String label, String shortLabel, int plane, int points, int hallPoints, int box, int bonusBox)
	{
		this.label = label;
		this.shortLabel = shortLabel;
		this.plane = plane;
		this.points = points;
		this.hallPoints = hallPoints;
		this.box = box;
		this.bonusBox = bonusBox;
	}

	/** Whether this room is the floor of the arena a player standing here is on. */
	boolean isOn(int region, int plane)
	{
		return this.plane >= 0 && region == REGION && plane == this.plane;
	}

	String label()
	{
		return label;
	}

	String shortLabel()
	{
		return shortLabel;
	}

	int points()
	{
		return points;
	}

	int hallPoints()
	{
		return hallPoints;
	}

	int box()
	{
		return box;
	}

	int bonusBox()
	{
		return bonusBox;
	}
}

