	PENTAMID("Pentamid",
		InterfaceID.MagictrainingEncha.MAGICTRAIN_ENCHA_LAYPENT,
		ItemID.MAGICTRAINING_ENCHAN_PENTAMID),
	ICOSAHEDRON("Icosahedron",
		InterfaceID.MagictrainingEncha.MAGICTRAIN_ENCHA_LAYICO,
		ItemID.MAGICTRAINING_ENCHAN_ICOSAHENDRON);

	private final String label;
	private final int layer;
	private final int item;

	Shape(String label, int layer, int item)
